const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedEntries = (t) => [...t.m.entries()].sort((a, b) => cmp(a[0], b[0]))

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const es = sortedEntries(n)
    if (!es.length) return '{}'
    return '{\n' + es.map(([k, v]) => `${pad}${JSON.stringify(k)}: ${toJson(v, ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function toKeys(n, path, out) {
  const kids = n.t === 'table' ? sortedEntries(n).map(([k, v]) => [(path ? path + '.' : '') + k, v])
